(function(root){
  'use strict';
  const KEY='jx3-appearance-v1', themes=['system','dark','light','jade'];
  const media=root.matchMedia('(prefers-color-scheme: dark)'), reduced=root.matchMedia('(prefers-reduced-motion: reduce)');
  let prefs={theme:'dark',ambient:true};
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){if(themes.includes(saved.theme))prefs.theme=saved.theme;if(typeof saved.ambient==='boolean')prefs.ambient=saved.ambient;}}catch{}
  function apply(){document.documentElement.dataset.theme=prefs.theme==='system'?(media.matches?'dark':'light'):prefs.theme;document.documentElement.dataset.themePreference=prefs.theme;document.documentElement.classList.toggle('ambient-off',!prefs.ambient);}
  function set(key,value){if(key==='theme'&&themes.includes(value))prefs.theme=value;if(key==='ambient')prefs.ambient=!!value;try{localStorage.setItem(KEY,JSON.stringify(prefs));}catch{}apply();sync();}
  function controls(){return '<div class="appearance-controls"><label>界面底色 <select class="select" data-appearance="theme" aria-label="界面底色">'+[['system','自动 · 跟随系统'],['dark','深色 · 星夜'],['light','浅色 · 宣纸'],['jade','青碧 · 山色']].map(([id,label])=>'<option value="'+id+'" '+(prefs.theme===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label class="ambient-switch"><input type="checkbox" data-appearance="ambient" '+(prefs.ambient?'checked':'')+'> 侠影动态背景</label></div>';}
  // Initial schools launched together. Later releases use the official chronology,
  // including Cangjian before Wudu despite their internal numeric force IDs.
  const releaseOrder = [
    'shaolin','wanhua','tiance','chunyang','qixiu','cangjian','wudu','tangmen','mingjiao',
    'gaibang','cangyun','changge','badao','penglai','lingxue','yantian','yaozong','daozong',
    'wanling','duanshi','wuxiang'
  ];
  function cast(){
    const atEntry = document.body.classList.contains('at-entry');
    const schools = atEntry ? releaseOrder : ['tangmen','qixiu','cangyun','chunyang','wanling','mingjiao','changge','tiance'];
    const people = schools.map((id,i) => {
      const atlas = root.JXData.SECTS.findIndex(sect => sect.id === id);
      const cell = '--cell-x:'+(100*(atlas%7)/6)+'%;--cell-y:'+(50*Math.floor(atlas/7))+'%';
      if(!atEntry) return '<div class="ambient-traveler traveler-'+i+'"><span class="cast-sprite" style="'+cell+'"></span></div>';
      const delay = i<5 ? i*.06 : 1.2+(i-5)*.45;
      const wave = Math.floor(i/7);
      const visit = wave ? wave*5+(i%7)*.25 : delay;
      const style = cell+';--visit:'+visit+'s;--arrival:'+delay+'s;--phase:-'+((i*2.17)%8)+'s;--scale:'+(.82+((i*7)%19)*.015)+';--step-x:'+(i%2?-1:1);
      return '<div class="entry-walker" data-sect="'+id+'" style="'+style+'"><div class="walker-arrival"><div class="walker-route"><i class="walker-shadow"></i><div class="walker-facing"><span class="cast-sprite"></span></div></div></div></div>';
    }).join('');
    return '<div class="ambient-cast'+(atEntry?' entry-cast':'')+'" aria-hidden="true">'+people+'</div>';
  }
  let entryObserver, walkTimer;
  function unmountEntry(){entryObserver?.disconnect();entryObserver=null;clearInterval(walkTimer);}
  function mountEntry(){
    unmountEntry();
    const field=document.querySelector('.entry-cast');
    const screen=field.closest('.login-screen');
    const obstacles=[...screen.querySelectorAll('.entry-appearance label,.entry-brand-copy,.entry-seal,.entry-story h1,.entry-poem,.entry-chips span,.entry-card,.entry-footer span')];
    let lanes=[], canStand, stride=0, phone=false;
    function place(lane) {
      for(const el of lane.actors){
        el.style.setProperty('--pos-x',lane.x+'px');el.style.setProperty('--pos-y',lane.y+'px');
        el.style.zIndex=Math.round(lane.y);
      }
    }
    function layout(){
      if(!field.clientWidth)return;
      phone=matchMedia('(max-width:760px)').matches;
      const rect=field.getBoundingClientRect(),width=rect.width,height=Math.min(rect.height,innerHeight);
      const blocked=obstacles.map(el=>{
        if(!el.matches('.entry-story h1,.entry-poem'))return el.getBoundingClientRect();
        const range=document.createRange();range.selectNodeContents(el);return range.getBoundingClientRect();
      });
      const walkers=[...field.children], count=phone?7:walkers.length;
      let size=phone?Math.min(48,width*.12):Math.min(90,width*.067,height*.105), spots=[];
      // Deterministic Poisson-disc sampling in the open scenery. No grid or rows.
      for(let attempt=0;attempt<8;attempt++,size*=.90){
        let seed=15931;
        const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
        spots=[];
        const margin=size*.66, maxY=phone?Math.min(height,screen.querySelector('.entry-card').getBoundingClientRect().top-rect.top):height;
        canStand=(x,y)=>x>=margin&&x<=width-margin&&y>=margin&&y<=maxY-margin&&!blocked.some(b=>x+margin>b.left-rect.left&&x-margin<b.right-rect.left&&y+margin>b.top-rect.top&&y-margin<b.bottom-rect.top);
        for(let tries=0;tries<3200&&spots.length<count;tries++){
          const x=margin+random()*(width-2*margin), y=margin+random()*(maxY-2*margin);
          if(!canStand(x,y))continue;
          // Leave a wider space between the five founders during their first entrance.
          const distance=spots.length<5&&!phone?Math.max(size*1.24,Math.min(width,height)*.24):size*1.13;
          if(spots.some(p=>Math.hypot(p.x-x,p.y-y)<distance))continue;
          spots.push({x,y});
        }
        if(spots.length===count)break;
      }
      if(spots.length<count)return;
      field.style.setProperty('--desktop-size',size+'px');
      stride=size;
      lanes=spots.map((spot,i)=>({...spot, actors:walkers.filter((_,n)=>n%count===i),
        next:performance.now()+900+((i*721)%2600), walking:false}));
      lanes.forEach(lane=>{
        lane.actors.forEach(el=>el.classList.remove('walking'));
        place(lane);
      });
    }
    function wander(){
      if(!field.isConnected){unmountEntry();return;}
      if(document.hidden||reduced.matches||!prefs.ambient||!field.clientWidth)return;
      const now=performance.now();
      for(const lane of lanes){
        if(now<lane.next)continue;
        lane.next=now+900+Math.random()*3100;
        if(lane.walking){
          lane.walking=false;lane.actors.forEach(el=>el.classList.remove('walking'));continue;
        }
        for(let n=0;n<18;n++){
          const angle=Math.random()*2*Math.PI, length=(.35+Math.random())*stride*(phone ? .64 : 1);
          const dx=Math.cos(angle)*length,dy=Math.sin(angle)*length;
          const x=lane.x+dx,y=lane.y+dy;
          if(!canStand(x,y)||!canStand(lane.x+dx/2,lane.y+dy/2))continue;
          if(lanes.some(other=>other!==lane&&Math.hypot(x-other.x,y-other.y)<stride*1.08))continue;
          const duration=Math.max(2,Math.round(length/18))*300;
          lane.actors.forEach(el=>{
            el.style.setProperty('--travel',duration+'ms');
            el.style.setProperty('--facing',dx>0?'1':'-1');
            el.classList.add('walking');
          });
          Object.assign(lane,{x,y,walking:true,next:now+duration});
          place(lane);break;
        }
      }
    }
    layout();
    entryObserver=new ResizeObserver(layout);
    [field,...obstacles].forEach(el=>entryObserver.observe(el));
    walkTimer=setInterval(wander,300);
  }
  function sync(){document.querySelectorAll('[data-appearance="theme"]').forEach(el=>el.value=prefs.theme);document.querySelectorAll('[data-appearance="ambient"]').forEach(el=>el.checked=prefs.ambient);}
  document.addEventListener('change',event=>{const key=event.target.dataset.appearance;if(key)set(key,key==='ambient'?event.target.checked:event.target.value);});
  media.addEventListener('change',apply);reduced.addEventListener('change',apply);apply();
  root.JXAppearance={controls,cast,mountEntry,unmountEntry,settings:()=>({...prefs}),set};
})(globalThis);

