    const m=hero.martialBuild,method=heartMethodFor(hero);if(!method||m.heartMethod!==method.id)return null;const rotation=m.equipped.filter(id=>allowed(id,method)&&(m.ranks[id]||0)>0);if(!rotation.length)return null;
