      uid:enemy?e.target.uid:e.actor.uid,attacker,defender,skillName:e.label,...(!challenge&&!status?{skillRank:e.skillRank||Math.max(1,Math.min(4,meta(e.actor)?.rarity||e.actor.rarity||1))}:{}),...visualFields(e),target:targetSide,
