    const from=battle.nextActor||0;
    let index=team.findIndex((h,i)=>i>=from&&h.hp>0);
    const opening=from===0||index<0;
    if(index<0)index=team.findIndex(h=>h.hp>0);
    if(opening)battle.turn++;
