    const specific=typeof assignment==='string'?(phase==='attack'?assignment:null):assignment?.[phase];
    if(phase==='impact')id=event.absorbed>0?'impact-block':event.critical?'impact-crit':c.skill?.damageType==='毒性'?'impact-poison':sect==='mingjiao'?'impact-fire':['wudu','yaozong','wanling','changge'].includes(sect)?'impact-nature':['chunyang','duanshi','penglai'].includes(sect)?'impact-qi':'impact';
