    function summary(){const s=state(),o=P.objective(s),p=P.current(s);return '<section class="journey-summary gui-journey-summary"><div><span class="eyebrow">第 '+(p.index+1)+' / '+D.EXPANSIONS.length+' 部 · 上限 Lv.'+p.levelCap+'</span><strong>'+esc(p.expansion.name)+'</strong><small>首通 '+o.cleared+' / '+o.total+' · '+(o.mode==='progress'?'自动推进':'重复刷取')+'</small></div>'+btn('地图路线','nav','map','small')+'</section>';}
