/* Shared page motion and disclosure state. */
(function(root){
  'use strict';
  let currentPage=null,currentTabs='',screenAnimations=[],enabled=true;
  let restoring=false,detailsState=new Map();
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const detailKey=el=>el.dataset.guiKey||el.querySelector('summary')?.textContent.trim()||'';
  function saveDetails(){if(!currentPage)return;document.querySelectorAll('#page details.gui-details').forEach(el=>detailsState.set(currentPage+'|'+detailKey(el),el.open));}
  function restoreDetails(){restoring=true;document.querySelectorAll('#page details.gui-details').forEach(el=>{const value=detailsState.get(currentPage+'|'+detailKey(el));if(value!==undefined)el.open=value;});restoring=false;}
  function syncMotion(){document.documentElement.dataset.guiMotion=enabled&&!reduced.matches?'on':'off';}
  reduced.addEventListener('change',syncMotion);
  function mount(options={}){
    const page=options.page||document.body.dataset.page;
    const changed=page!==currentPage;
    enabled=options.motion!==false;syncMotion();
    currentPage=page;
    restoreDetails();
    const screen=document.querySelector('#page');
    const tabs=[...screen.querySelectorAll(':is(.tabs,.card-tabs,.shop-tabs,.growth-tabs,.growth-role-tabs,.growth-color-tabs) [data-action].active')]
      .map(el=>el.dataset.action+'='+el.dataset.id).join('/');
    const transition=changed||tabs!==currentTabs;
    if(transition||!enabled||reduced.matches){
      for(const animation of screenAnimations)animation.cancel();
      screenAnimations=[];
    }
    if(transition&&enabled&&!reduced.matches){
      // The page fills the viewport. Move the content inside its padding so
      // the 6px entrance never creates a scrollbar on a single-screen view.
      const timing={duration:250,easing:'ease'};
      screenAnimations.push(screen.animate([{opacity:0},{opacity:1}],timing));
      for(const child of screen.children){
        if(!child.hidden)screenAnimations.push(child.animate([{translate:'0 6px'},{translate:'0 0'}],timing));
      }
    }
    currentTabs=tabs;
  }
  document.addEventListener('toggle',event=>{if(!restoring&&event.target.matches?.('details.gui-details')&&currentPage)detailsState.set(currentPage+'|'+detailKey(event.target),event.target.open);},true);
  root.JXGui={mount,beforeRender:saveDetails};
})(globalThis);

