      const hearts='<div class="martial-heart-switch" aria-label="主角心法">'+info.methods.map(method=>'<button class="btn small '+(method.id===info.method.id?'active':'')+'" data-action="martial-heart" data-id="'+method.id+'">'+esc(method.name)+' <small>'+({melee:'近战',ranged:'远程'}[method.range])+'</small></button>').join('')+'</div>';
