    return {name:(set?set+'·':'')+slot.name,kind:'掉落预览',art:root.JXPixelIcons.gear({slot:slotId,rarity,sect:D.HEROES.find(x=>x.id===hero(s).id)?.sect}),place:'预览',tags:[quality[rarity],tier],facts:[['部位',slot.name],['镶孔',slot.sockets]],desc:set?'本章门派套装部件，集齐2、4、6件激活套装效果。':'此处展示可掉落部位，获得装备后可查看实际属性。',source:d?.name||'野外历练'};
