    const resources={silver:['银两','silver',s.silver,'购买补给、百工制作与装备强化。','历练 · 副本 · 活动'],jade:['通宝','jade',s.jade,'在通宝商店购买珍稀外观。','江湖活动'],renown:['侠名','renown',s.renown,'兑换团队装备和强化材料。','秘境 · 活动'],currency:[chapter.currencyName,'jade',chapter.record.currency,'在资料片商店兑换本章货物。',ch.name+' · 百战与活动'],supplies:['副本补给','supplies',s.progression.supplies,'进入对应秘境时消耗。','定时恢复与活动'],cultivation:['修为','star',s.martial?.cultivation||0,'门派传功累积冲穴修为。主角获得的历练修为可用于经脉冲穴，同时推进角色等级。','历练 · 门派传功 · 修为丹'],geodes:['藏宝洞宝箱','gift',t.geodes,'在藏宝洞开箱获得奖励。','藏宝洞探险'],tokens:['藏宝洞积分','coin',t.tokens,'兑换货物、开启第二处探险位置。','藏宝洞探险'],gear:['装备','gear',s.equipment.bag.length,'战利品按实际掉落部位进入装备行囊。','秘境首领 · 江湖历练']};
