        const index=radios.indexOf(event.target),length=radios.length;
        const next={ArrowLeft:(index+length-1)%length,ArrowUp:(index+length-1)%length,
          ArrowRight:(index+1)%length,ArrowDown:(index+1)%length,Home:0,End:length-1}[event.key];
        if(next!==undefined){event.preventDefault();radios[next].focus();radios[next].click();}
