  const $ = q => document.querySelector(q);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = n => Math.floor(Number(n)||0).toLocaleString('zh-CN');
  const pct = (a,b) => Math.max(0,Math.min(100,(a/(b||1))*100));
