  function openModal(html,cls=''){const m=$('#modal'),sameHero=m.open&&ui.heroModal&&m.querySelector('.modal-head h2')?.textContent===meta(ui.heroModal)?.name,scrolls=sameHero?JXScroll.capture(m):null;m.className=cls;m.innerHTML=html;JXReferenceUI.clean(m);if(!m.open)m.showModal();if(scrolls)JXScroll.restore(m,scrolls);else m.scrollTop=0;}
