  function navBadge(button,count){
    count=Number(count)||0;
    if((Number(button.dataset.rewardCount)||0)===count)return;
    button.dataset.rewardCount=String(count);
    button.querySelector('.reward-badge')?.remove();
    if(count){
      const chevron=button.querySelector('.nav-expand');
      (chevron||button).insertAdjacentHTML(chevron?'beforebegin':'beforeend',JXRewards.badge(count));
    }
    if(button.hasAttribute('aria-label')){
      const label=button.querySelector('.nav-label')?.textContent;
      if(label)button.setAttribute('aria-label',label+(count?'，'+count+' 项可领取':''));
    }
  }
  function syncSidebar(){
    const sidebar=$('#sidebar');if(!sidebar)return;
    const phone=navPhone.matches, counts=rewardCounts();
    const selectedPage=['activity-world','activity-underground','activity-tower'].includes(ui.page)?'challenges':ui.page;
    if(ui.page!==lastNavPage){
      const owner=navigation.find(([, , ,children])=>children?.some(([page])=>page===selectedPage));
      if(owner)persistNav(owner[0],true);
      navSheet='';lastNavPage=ui.page;
    }
    sidebar.classList.toggle('has-sheet',phone&&!!navSheet);
    for(const button of sidebar.querySelectorAll('#sidebar-pages > button,.sidebar-bottom button,#chapter-card')){
      const active=ui.page===button.dataset.id;
      currentNav(button,active,active&&(button.dataset.id!=='adventure'||phone===(button.id!=='chapter-card')));
      navBadge(button,counts[button.dataset.id]);
    }
    for(const group of sidebar.querySelectorAll('[data-nav-group]')){
      const id=group.dataset.navGroup,header=group.firstElementChild,body=header.nextElementSibling;
      const open=phone?navSheet===id:!!navExpanded[id];
      if(!open&&body.contains(document.activeElement))header.focus({preventScroll:true});
      group.classList.toggle('open',!phone&&open);group.classList.toggle('sheet',phone&&open);
      header.setAttribute('aria-expanded',String(open));body.inert=!open;
      let total=0,selected=false;
      for(const row of body.querySelectorAll('button')){
        const page=row.dataset.id, active=page===selectedPage, count=counts[page]||0;
        selected||=active;total+=count;
        currentNav(row,active,active&&open);navBadge(row,count);
        if(!open||id!=='activities'&&page!=='activity-support')continue;
        const status=page==='activity-dungeon'?{}:AUI.status(page),text=count||status.ready?'':status.badge||'',label=row.querySelector('.nav-status');
        if(label.textContent!==text)label.textContent=text;
        label.hidden=!text;label.classList.toggle('locked',!!status.locked);
      }
      currentNav(header,selected&&(phone||!open),selected&&!open);
      navBadge(header,open?0:total);
    }
  }
